package com.example.statusdrafter.controller; import com.example.statusdrafter.dto.RegistrationForm; import com.example.statusdrafter.service.UserService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller public class AuthController {private final UserService users;public AuthController(UserService u){users=u;} @GetMapping("/login")String login(){return "auth/login";} @GetMapping("/register")String reg(Model m){m.addAttribute("form",new RegistrationForm());return "auth/register";} @PostMapping("/register")String register(@Valid @ModelAttribute("form")RegistrationForm f,BindingResult br,Model m){if(br.hasErrors())return "auth/register";try{users.register(f);return "redirect:/login?registered";}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());return "auth/register";}} @GetMapping("/forgot-password")String forgot(){return "auth/forgot-password";}}
